        ("1B", "Birchwood", -1109, -404, 500, 150, 184, CAVE_KEEL, "Birch"),
        ("1C", "Gorgeback", 1109, -404, 520, 152, 196, CAVE_KEEL, "Gorge"),
        ("1D", "Fenmoss", 0, -1060, 420, 148, 180, 50, "Swamp"),
