        assert _blk in [r_[5] for r_ in Z7_MR] + [r_[6] for r_ in Z7_MR], "a mirror rule places this block: " + _blk
        for _ref in (_htex, "Resources/Ores/Ore_Large.blockymodel", "Resources/Materials/Ingot.blockymodel"):
            assert ("Common/" + _ref) in _nm, "vanilla file missing: " + _ref
        assert _cob in _itm, "vanilla cobble " + _cob
