M(isl, r"""
public static double vnoise(double x, double z, double scale, int salt) {
  double fx = x / scale;
  double fz = z / scale;
  double flx = Math.floor(fx);
  double flz = Math.floor(fz);
  int ix = (int) flx;
  int iz = (int) flz;
  double tx = fx - flx;
  double tz = fz - flz;
  tx = tx * tx * (3.0 - 2.0 * tx);
  tz = tz * tz * (3.0 - 2.0 * tz);
  double a = hash(ix, iz, salt);
  double b = hash(ix + 1, iz, salt);
  double c = hash(ix, iz + 1, salt);
  double d = hash(ix + 1, iz + 1, salt);
  double ab = a + (b - a) * tx;
  double cd = c + (d - c) * tx;
  return ab + (cd - ab) * tz;
}""")
