M(isl, r"""
public static @PKG@.WgIsleGen genOf(@WLD@ w) {
  try {
    if (w == null || w.getChunkStore() == null) return null;
    Object g = w.getChunkStore().getGenerator();
    return g instanceof @PKG@.WgIsleGen ? (@PKG@.WgIsleGen) g : null;
  } catch (Throwable t) { return null; }
}""")
M(isl, r"""
public static String placeAt(@WLD@ w, double x, double y, double z) {
  @PKG@.WgIsleGen g = genOf(w);
  if (g == null) return "the island generator is not running on this world";
  if (!g.centred) return "the island centre is not known yet (no chunk generated so far)";
  double rx = x - g.ox;
  double rz = z - g.oz;
  String s = @PKG@.WgZones.proofPlace(rx, rz);
  int seed = (int) w.getWorldConfig().getSeed();
  int ix = (int) Math.floor(x);
  int iz = (int) Math.floor(z);
  try {
    @ZBR@ r = g.getZoneBiomeResultAt(seed, ix, iz);
    if (r != null) s = s + "; vanilla zone " + r.getZoneResult().getZone().name() + ", biome " + r.getBiome().getName();
  } catch (Throwable t) { }
  double[] m = new double[2];
  double cxr = ix + 0.5 - g.ox;
  double czr = iz + 0.5 - g.oz;
  if (member(cxr, czr, m)) {
    try {
      int h = g.getHeight(seed, ix, iz);
      s = s + "; island underside here y " + bottomOf(m, h, cxr, czr) + " (vanilla ground y " + h + ")";
    } catch (Throwable t) { s = s + "; on the island mask (the underside height is not available here)"; }
  } else s = s + "; outside the island mask (void)";
  return s;
}""")
