# 3-4 chamfer distance (3 per cell step) to the nearest 0 cell; out-of-grid neighbours count as 'edge' (3 = a source, BIG = never)
M(zisl, r"""
public static void chamfer(int[] d, int w, int h, int edge) {
  for (int z = 0; z < h; z++) {
    for (int x = 0; x < w; x++) {
      int i = z * w + x;
      int v = d[i];
      if (v == 0) continue;
      int a = x > 0 ? d[i - 1] + 3 : edge;
      if (a < v) v = a;
      a = z > 0 ? d[i - w] + 3 : edge;
      if (a < v) v = a;
      a = (x > 0 && z > 0) ? d[i - w - 1] + 4 : edge + 1;
      if (a < v) v = a;
      a = (x + 1 < w && z > 0) ? d[i - w + 1] + 4 : edge + 1;
      if (a < v) v = a;
      d[i] = v;
    }
  }
  for (int z = h - 1; z >= 0; z--) {
    for (int x = w - 1; x >= 0; x--) {
      int i = z * w + x;
      int v = d[i];
      if (v == 0) continue;
      int a = x + 1 < w ? d[i + 1] + 3 : edge;
      if (a < v) v = a;
      a = z + 1 < h ? d[i + w] + 3 : edge;
      if (a < v) v = a;
      a = (x + 1 < w && z + 1 < h) ? d[i + w + 1] + 4 : edge + 1;
      if (a < v) v = a;
      a = (x > 0 && z + 1 < h) ? d[i + w - 1] + 4 : edge + 1;
      if (a < v) v = a;
      d[i] = v;
    }
  }
}""")
# BFS over ok[] from start (4 neighbours); marks mark[], the cells land in q[0 .. return-1]
M(zisl, r"""
public static int flood(boolean[] ok, boolean[] mark, int[] q, int n, int start) {
  int qh = 0;
  int qt = 0;
  mark[start] = true;
  q[qt] = start;
  qt++;
  while (qh < qt) {
    int p = q[qh];
    qh++;
    int px = p % n;
    int pz = p / n;
    if (px > 0 && ok[p - 1] && !mark[p - 1]) { mark[p - 1] = true; q[qt] = p - 1; qt++; }
    if (px + 1 < n && ok[p + 1] && !mark[p + 1]) { mark[p + 1] = true; q[qt] = p + 1; qt++; }
    if (pz > 0 && ok[p - n] && !mark[p - n]) { mark[p - n] = true; q[qt] = p - n; qt++; }
    if (pz + 1 < n && ok[p + n] && !mark[p + n]) { mark[p + n] = true; q[qt] = p + n; qt++; }
  }
  return qt;
}""")
# one island's signed distance grid: its class's land inside the wobbled radius, the piece nearest the centre, enclosed holes filled
# when small or sea, then sd = + blocks to the coast inside / - blocks to the land outside (capped at NEG_SD)
M(zisl, r"""
public static void buildIsland(@PKG@.WgZoneLayout L, int i, java.util.function.IntBinaryOperator smp) {
  int ec = ((int) Math.ceil(L.rad[i]) + MARGIN) / CELL + 1;
  int n = 2 * ec + 1;
  int ox = (int) Math.floor(L.cx[i]) - ec * CELL;
  int oz = (int) Math.floor(L.cz[i]) - ec * CELL;
  int want = L.cls[i];
  int nn = n * n;
  byte[] c = new byte[nn];
  boolean[] in = new boolean[nn];
  int start = 0 - 1;
  double sd0 = 1.0E18;
  for (int k = 0; k < n; k++) {
    for (int j = 0; j < n; j++) {
      int x = ox + j * CELL;
      int z = oz + k * CELL;
      int cl = smp.applyAsInt(x, z);
      int p = k * n + j;
      c[p] = (byte) cl;
      double dx = x - L.cx[i];
      double dz = z - L.cz[i];
      double d = Math.sqrt(dx * dx + dz * dz);
      boolean ok = cl == want && d + wobR((double) x, (double) z) <= L.rad[i];
      in[p] = ok;
      if (ok && d < sd0) { sd0 = d; start = p; }
    }
  }
  L.gx0[i] = ox;
  L.gz0[i] = oz;
  L.gn[i] = n;
  if (start < 0) { L.found[i] = false; return; }
  boolean[] keep = new boolean[nn];
  int[] q = new int[nn];
  flood(in, keep, q, n, start);
  boolean[] notKeep = new boolean[nn];
  for (int p = 0; p < nn; p++) notKeep[p] = !keep[p];
  boolean[] outs = new boolean[nn];
  for (int t = 0; t < n; t++) {
    int a = t;
    int b = (n - 1) * n + t;
    int e = t * n;
    int f = t * n + n - 1;
    if (notKeep[a] && !outs[a]) flood(notKeep, outs, q, n, a);
    if (notKeep[b] && !outs[b]) flood(notKeep, outs, q, n, b);
    if (notKeep[e] && !outs[e]) flood(notKeep, outs, q, n, e);
    if (notKeep[f] && !outs[f]) flood(notKeep, outs, q, n, f);
  }
  boolean[] inside = new boolean[nn];
  boolean[] hole = new boolean[nn];
  for (int p = 0; p < nn; p++) { inside[p] = keep[p]; hole[p] = !keep[p] && !outs[p]; }
  boolean[] seen = new boolean[nn];
  int filled = 0;
  int holes = 0;
  for (int p = 0; p < nn; p++) {
    if (!hole[p] || seen[p]) continue;
    int cnt = flood(hole, seen, q, n, p);
    int foreign = 0;
    for (int t = 0; t < cnt; t++) { int cc = c[q[t]]; if (cc != 0 && cc != want) foreign++; }
    if (cnt <= HOLE_FILL || foreign == 0) {
      for (int t = 0; t < cnt; t++) inside[q[t]] = true;
      filled += cnt;
    } else holes++;
  }
  int[] din = new int[nn];
  int[] dout = new int[nn];
  for (int p = 0; p < nn; p++) { din[p] = inside[p] ? BIG : 0; dout[p] = inside[p] ? 0 : BIG; }
  chamfer(din, n, n, 3);
  chamfer(dout, n, n, BIG);
  float[] sd = new float[nn];
  long cntIn = 0L;
  double mx = 0.0;
  int best = 0 - 1;
  int x0 = 1000000000;
  int x1 = 0 - 1000000000;
  int z0 = 1000000000;
  int z1 = 0 - 1000000000;
  for (int p = 0; p < nn; p++) {
    double v;
    if (inside[p]) {
      v = din[p] * CELLD / 3.0;
      cntIn++;
      int x = ox + (p % n) * CELL;
      int z = oz + (p / n) * CELL;
      if (x < x0) x0 = x;
      if (x > x1) x1 = x;
      if (z < z0) z0 = z;
      if (z > z1) z1 = z;
      if (best < 0 || v > mx) { mx = v; best = p; }
    } else {
      v = 0.0 - dout[p] * CELLD / 3.0;
      if (v < OUTSD) v = OUTSD;
    }
    sd[p] = (float) v;
  }
  L.sd[i] = sd;
  L.area[i] = cntIn * CELL * CELL;
  L.filled[i] = filled;
  L.holes[i] = holes;
  L.maxsd[i] = mx;
  L.minX[i] = x0;
  L.maxX[i] = x1;
  L.minZ[i] = z0;
  L.maxZ[i] = z1;
  L.found[i] = cntIn > 0L;
  if (best >= 0) { L.lx[i] = ox + (best % n) * CELL; L.lz[i] = oz + (best / n) * CELL; }
}""")
# the sd grid value at a world point (bilinear); OUTSD outside the grid
M(zisl, r"""
public static double sdAt(@PKG@.WgZoneLayout L, int i, double x, double z) {
  int n = L.gn[i];
  float[] s = L.sd[i];
  if (s == null) return OUTSD;
  double gx = (x - L.gx0[i]) / CELLD;
  double gz = (z - L.gz0[i]) / CELLD;
  if (gx < 0.0 || gz < 0.0 || gx >= n - 1 || gz >= n - 1) return OUTSD;
  int ix = (int) gx;
  int iz = (int) gz;
  double tx = gx - ix;
  double tz = gz - iz;
  int p = iz * n + ix;
  double a = s[p];
  double b = s[p + 1];
  double c = s[p + n];
  double d = s[p + n + 1];
  double ab = a + (b - a) * tx;
  double cd = c + (d - c) * tx;
  return ab + (cd - ab) * tz;
}""")
# THE island picker: Zone 1 at the vanilla spawn; Zones 2-5 at the deepest land of their class near the spawn, GAP apart (fallbacks
# logged); then each island's grid. Deterministic: a pure function of the sampler (the seed's vanilla zone map) and the spawn point
M(zisl, r"""
public static @PKG@.WgZoneLayout layout(java.util.function.IntBinaryOperator smp, double spx, double spz, int seed) {
  long t0 = System.currentTimeMillis();
  int n = Z_IDS.length;
  @PKG@.WgZoneLayout L = new @PKG@.WgZoneLayout(n);
  L.seed = seed;
  L.spx = spx;
  L.spz = spz;
  int w = 2 * HALF + 1;
  int bx = (int) Math.floor(spx / STEP) * STEP - HALF * STEP;
  int bz = (int) Math.floor(spz / STEP) * STEP - HALF * STEP;
  byte[] g = new byte[w * w];
  for (int k = 0; k < w; k++) for (int j = 0; j < w; j++) g[k * w + j] = (byte) smp.applyAsInt(bx + j * STEP, bz + k * STEP);
  L.spawnCls = smp.applyAsInt((int) Math.floor(spx), (int) Math.floor(spz));
  int[][] dt = new int[5][];
  for (int c = 1; c <= 4; c++) {
    int[] d = new int[w * w];
    for (int p = 0; p < w * w; p++) d[p] = g[p] == c ? BIG : 0;
    chamfer(d, w, w, 3);
    dt[c] = d;
  }
  for (int i = 0; i < n; i++) { L.rad[i] = Z_R[i]; L.cls[i] = Z_CLS[i]; }
  L.cx[0] = spx;
  L.cz[0] = spz;
  L.found[0] = true;
  L.gapUsed[0] = GAP;
  double[] gaps = new double[] { GAP, GAP2, GAP3 };
  double[] deps = new double[] { MIN_DEPTH, MIN_DEPTH * 0.5 };
  for (int i = 1; i < n; i++) {
    int c = Z_CLS[i];
    int[] d = dt[c];
    boolean got = false;
    for (int gi = 0; gi < gaps.length && !got; gi++) {
      for (int di = 0; di < deps.length && !got; di++) {
        double best = 0.0;
        int bp = 0 - 1;
        for (int p = 0; p < w * w; p++) {
          if (g[p] != c) continue;
          double dep = d[p] * (double) STEP / 3.0;
          if (dep < deps[di]) continue;
          double x = bx + (p % w) * STEP;
          double z = bz + (p / w) * STEP;
          boolean clear = true;
          for (int j = 0; j < i && clear; j++) {
            if (!L.found[j]) continue;
            double dx = x - L.cx[j];
            double dz = z - L.cz[j];
            if (Math.sqrt(dx * dx + dz * dz) < Z_R[i] + Z_R[j] + gaps[gi]) clear = false;
          }
          if (!clear) continue;
          double ex = x - spx;
          double ez = z - spz;
          double sc = Math.min(dep, CAP_F * Z_R[i]) - DIST_W * Math.sqrt(ex * ex + ez * ez);
          if (bp < 0 || sc > best) { best = sc; bp = p; }
        }
        if (bp >= 0) {
          L.cx[i] = bx + (bp % w) * STEP;
          L.cz[i] = bz + (bp / w) * STEP;
          L.found[i] = true;
          L.gapUsed[i] = gaps[gi];
          got = true;
        }
      }
    }
  }
  for (int i = 0; i < n; i++) if (L.found[i]) buildIsland(L, i, smp);
  if (L.found[0]) { L.lx[0] = spx; L.lz[0] = spz; }
  L.ms = System.currentTimeMillis() - t0;
  LAYOUTS.incrementAndGet();
  return L;
}""")
M(zisl, r"""
public static String layoutText(@PKG@.WgZoneLayout L) {
  if (L == null) return "no island layout yet";
  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < L.n; i++) {
    if (i > 0) sb.append("; ");
    sb.append("Zone ").append(Z_IDS[i]).append(' ').append(Z_NAMES[i]);
    if (!L.found[i]) { sb.append(" NOT FOUND (no vanilla land of its zone near the spawn)"); continue; }
    sb.append(" at ").append(Math.round(L.cx[i])).append(' ').append(Math.round(L.cz[i]));
    sb.append(" (").append(Math.round(L.area[i] / 10000.0) / 100.0).append(" km2, ").append(L.maxX[i] - L.minX[i] + CELL).append(" x ").append(L.maxZ[i] - L.minZ[i] + CELL).append(" blocks");
    if (i > 0 && L.gapUsed[i] < GAP) sb.append(", gap relaxed to ").append(Math.round(L.gapUsed[i]));
    if (L.holes[i] > 0) sb.append(", ").append(L.holes[i]).append(" void holes");
    sb.append(')');
  }
  sb.append(" - picked from the vanilla zone map in ").append(L.ms).append(" ms");
  if (L.spawnCls != 1) sb.append(" (WARNING: the vanilla spawn point is not on Zone 1 land, class ").append(L.spawnCls).append(')');
  return sb.toString();
}""")
# island index (0-4) of a column, out[0] = its distance in from the coast (blocks, wobbled); -1 = void
M(zisl, r"""
public static int member(@PKG@.WgZoneLayout L, double x, double z, double[] out) {
  if (L == null) return 0 - 1;
  for (int i = 0; i < L.n; i++) {
    if (!L.found[i] || L.sd[i] == null) continue;
    double e = sdAt(L, i, x, z);
    if (e + CW_MAX <= 0.0) continue;
    e = e + coastWob(x, z);
    if (e > 0.0) { out[0] = e; return i; }
  }
  return 0 - 1;
}""")
# the underside y of an island column (the 0.5 recipe by distance from the coast) + stone drips under the skirt
M(zisl, r"""
public static int bottomOf(double e, int h, double x, double z) {
  double t = 1.0 - e / SKIRT;
  if (t < 0.0) t = 0.0;
  if (t > 1.0) t = 1.0;
  double sm = t * t * (3.0 - 2.0 * t);
  double b = KEEL + (RIM_BOT - KEEL) * sm + RA * @PKG@.WgIsle.vnoise(x, z, RS, 37) * sm;
  if (sm > 0.0) {
    double dv = @PKG@.WgIsle.vnoise(x, z, DRIP_S, 83);
    if (dv > DRIP_T) {
      double q = (dv - DRIP_T) / (1.0 - DRIP_T);
      b = b - DRIP * q * q * Math.min(1.0, sm * 3.0);
    }
    b = Math.min(b, (double) h - MIN_THICK);
  }
  if (b < KEEL) b = KEEL;
  return (int) Math.floor(b);
}""")
# a chunk with no island column (conservative: any grid point near the chunk within the coast wobble keeps it)
M(zisl, r"""
public static boolean chunkOutside(@PKG@.WgZoneLayout L, int cx, int cz) {
  if (L == null) return false;
  double x0 = cx * 32.0;
  double z0 = cz * 32.0;
  for (int i = 0; i < L.n; i++) {
    if (!L.found[i] || L.sd[i] == null) continue;
    int n = L.gn[i];
    int j0 = (int) Math.floor((x0 - L.gx0[i]) / CELLD) - 1;
    int j1 = (int) Math.floor((x0 + 32.0 - L.gx0[i]) / CELLD) + 1;
    int k0 = (int) Math.floor((z0 - L.gz0[i]) / CELLD) - 1;
    int k1 = (int) Math.floor((z0 + 32.0 - L.gz0[i]) / CELLD) + 1;
    if (j1 < 0 || k1 < 0 || j0 > n - 1 || k0 > n - 1) continue;
    if (j0 < 0) j0 = 0;
    if (k0 < 0) k0 = 0;
    if (j1 > n - 1) j1 = n - 1;
    if (k1 > n - 1) k1 = n - 1;
    float[] s = L.sd[i];
    for (int k = k0; k <= k1; k++) for (int j = j0; j <= j1; j++) if (s[k * n + j] + EDGE_PAD > 0.0) return false;
  }
  return true;
}""")
M(zisl, "public static int blk(String nm) { try { return @BT@.getAssetMap().getIndexOrDefault(nm, -1); } catch (Throwable t) { return -1; } }")
M(zisl, r"""
public static int[] blks(String[] nms) {
  int[] a = new int[nms.length];
  for (int i = 0; i < nms.length; i++) a[i] = blk(nms[i]);
  return a;
}""")
M(zisl, r"""
public static boolean has(int[] a, int v) {
  if (a == null || v <= 0) return false;
  for (int i = 0; i < a.length; i++) if (a[i] == v) return true;
  return false;
}""")
M(zisl, r"""
public static void ids() {
  if (IDS) return;
  int st = blk(SEAL);
  int ev = 0 - 1;
  try { ev = @ENV@.getAssetMap().getIndexOrDefault(VOID_ENV, -1); } catch (Throwable t) { ev = 0 - 1; }
  int[] all = blks(GROUND_ALL);
  int[][] gr = new int[GROUND_AT.length - 1][];
  for (int i = 0; i + 1 < GROUND_AT.length; i++) {
    int[] a = new int[GROUND_AT[i + 1] - GROUND_AT[i]];
    for (int j = 0; j < a.length; j++) a[j] = all[GROUND_AT[i] + j];
    gr[i] = a;
  }
  GROUND = gr;
  FLOWERS = blks(FLOWER_NAMES);
  DECO = blks(DECO_NAMES);
  ORE = blks(ORE_NAMES);
  HOST = blks(HOST_NAMES);
  STONE = st;
  ENVV = ev;
  FLE = @FL@.EMPTY_ID;
  IDS = true;
  int miss = 0;
  for (int i = 0; i < DECO.length; i++) if (DECO[i] < 0) miss++;
  for (int i = 0; i < ORE.length; i++) if (ORE[i] < 0) miss++;
  if (st < 0 && @PKG@.WgLog.once("zstone")) @PKG@.WgLog.error("zone islands: block " + SEAL + " is not loaded - the underside skin can only drain fluids (no stone) until it is");
  if (miss > 0 && @PKG@.WgLog.once("zdeco")) @PKG@.WgLog.warn("zone islands: " + miss + " decoration / ore block(s) are not loaded - those are skipped (is the SkyyWorldGen asset pack loaded?)");
}""")
M(zisl, r"""
public static int fluidAt(@FS@[] fs, int lx, int y, int lz) {
  if (y < 0 || y > 319) return FLE;
  @FS@ f = fs[y >> 5];
  return f == null ? FLE : f.getFluidId(lx, y, lz);
}""")
M(zisl, r"""
public static void clearVoxel(@GC@ gc, @GBC@ bc, @FS@[] fs, int lx, int y, int lz) {
  int b = bc.getBlock(lx, y, lz);
  if (b != 0) {
    if (gc.getState(lx, y, lz) != null) gc.setState(lx, y, lz, null);
    bc.setBlock(lx, y, lz, 0, 0, 0);
    CLEARED.incrementAndGet();
  }
  @FS@ f = fs[y >> 5];
  if (f != null && f.getFluidId(lx, y, lz) != FLE) f.setFluid(lx, y, lz, FLE, (byte) 0);
}""")
M(zisl, r"""
public static void clearColumn(@GC@ gc, @GBC@ bc, @FS@[] fs, int lx, int lz, int y0, int y1) {
  if (y1 > 320) y1 = 320;
  for (int sy = y0 >> 5; sy < 10 && sy * 32 < y1; sy++) {
    if (bc.getSection(sy * 32) == null && fs[sy] == null) continue;
    int a = Math.max(y0, sy * 32);
    int e = Math.min(y1, sy * 32 + 32);
    for (int y = a; y < e; y++) clearVoxel(gc, bc, fs, lx, y, lz);
  }
}""")
M(zisl, r"""
public static void sealVoxel(@GC@ gc, @GBC@ bc, @FS@[] fs, int lx, int y, int lz) {
  @FS@ f = fs[y >> 5];
  if (f != null && f.getFluidId(lx, y, lz) != FLE) f.setFluid(lx, y, lz, FLE, (byte) 0);
  if (STONE >= 0) {
    if (bc.getBlock(lx, y, lz) != 0 && gc.getState(lx, y, lz) != null) gc.setState(lx, y, lz, null);
    bc.setBlock(lx, y, lz, STONE, 0, 0);
  }
  SEALED.incrementAndGet();
}""")
# ---- RICHER LOOKS (vanilla blocks only): the ground = the first solid block from above (no fluid on / over it, never leaves / logs /
# buildings: only the zone's natural ground blocks count), placements only into empty, fluid-free voxels of this chunk
# the highest block of a column in the generated chunk (any block: leaves / logs / buildings too); -1 = none. Cheap (empty sections
# skipped) - the mask asks vanilla's terrain height only where the underside needs it (the coast band), never for decoration / ores
M(zisl, r"""
public static int topBlock(@GBC@ bc, int lx, int lz) {
  for (int sy = 9; sy >= 0; sy--) {
    if (bc.getSection(sy * 32) == null) continue;
    for (int y = sy * 32 + 31; y >= sy * 32; y--) if (bc.getBlock(lx, y, lz) != 0) return y;
  }
  return 0 - 1;
}""")
M(zisl, r"""
public static int topOf(@GBC@ bc, @FS@[] fs, int lx, int lz, int top, int b) {
  if (top < b + SHELL || top > 318) return 0 - 1;
  if (fluidAt(fs, lx, top, lz) != FLE || fluidAt(fs, lx, top + 1, lz) != FLE) return 0 - 1;
  return top;
}""")
M(zisl, r"""
public static boolean free(@GBC@ bc, @FS@[] fs, int lx, int y, int lz) {
  return y >= 1 && y <= 318 && bc.getBlock(lx, y, lz) == 0 && fluidAt(fs, lx, y, lz) == FLE;
}""")
M(zisl, r"""
public static boolean put(@GBC@ bc, @FS@[] fs, int lx, int y, int lz, int id) {
  if (id <= 0 || !free(bc, fs, lx, y, lz)) return false;
  bc.setBlock(lx, y, lz, id, 0, 0);
  DECO_N.incrementAndGet();
  return true;
}""")
M(zisl, r"""
public static void pillar(@GBC@ bc, @FS@[] fs, int lx, int top, int lz, int hgt, int body, int band, int cap) {
  if (body <= 0) return;
  for (int t = 1; t <= hgt; t++) if (!free(bc, fs, lx, top + t, lz)) return;
  for (int t = 1; t <= hgt; t++) {
    int id = body;
    if (t == hgt && cap > 0) id = cap;
    else if (band > 0 && t % 3 == 2) id = band;
    bc.setBlock(lx, top + t, lz, id, 0, 0);
    DECO_N.incrementAndGet();
  }
}""")
M(zisl, r"""
public static void boulder(@GBC@ bc, @FS@[] fs, int lx, int lz, int top, int[] tops, int id, int x, int z) {
  if (id <= 0 || lx > 30 || lz > 30) return;
  if (tops[(lx + 1) * 32 + lz] != top || tops[lx * 32 + lz + 1] != top || tops[(lx + 1) * 32 + lz + 1] != top) return;
  for (int a = 0; a < 2; a++) for (int c = 0; c < 2; c++) if (!free(bc, fs, lx + a, top + 1, lz + c) || !free(bc, fs, lx + a, top + 2, lz + c)) return;
  for (int a = 0; a < 2; a++) {
    for (int c = 0; c < 2; c++) {
      bc.setBlock(lx + a, top + 1, lz + c, id, 0, 0);
      DECO_N.incrementAndGet();
      if (hash01(x + a, z + c, 109) < 0.6) { bc.setBlock(lx + a, top + 2, lz + c, id, 0, 0); DECO_N.incrementAndGet(); }
    }
  }
}""")
M(zisl, r"""
public static void crack(@GBC@ bc, @FS@[] fs, int lx, int top, int lz) {
  int id = DECO[D_CRACK];
  if (id <= 0 || !free(bc, fs, lx, top + 1, lz)) return;
  bc.setBlock(lx, top, lz, id, 0, 0);
  DECO_N.incrementAndGet();
}""")
M(zisl, r"""
public static void decorate(@GBC@ bc, @FS@[] fs, int bx, int bz, int[] bot, int[] tb, int[] isl, double[] ee) {
  int[] tops = new int[32 * 32];
  for (int lx = 0; lx < 32; lx++) {
    for (int lz = 0; lz < 32; lz++) {
      int idx = (lx + 1) * 34 + (lz + 1);
      tops[lx * 32 + lz] = 0 - 1;
      int ii = isl[idx];
      if (ii < 0 || ii >= GROUND.length || ee[idx] < DECO_EDGE) continue;
      int t = topOf(bc, fs, lx, lz, tb[lx * 32 + lz], bot[idx]);
      if (t >= 0 && has(GROUND[ii], bc.getBlock(lx, t, lz))) tops[lx * 32 + lz] = t;
    }
  }
  for (int lx = 0; lx < 32; lx++) {
    for (int lz = 0; lz < 32; lz++) {
      int idx = (lx + 1) * 34 + (lz + 1);
      int ii = isl[idx];
      if (ii < 0) continue;
      int x = bx + lx;
      int z = bz + lz;
      if (ii <= 2 && ee[idx] < SKIRT * 0.8 && hash01(x, z, 97) < ROOT_P) {
        int len = 1 + (int) (hash01(x, z, 98) * 3.0);
        for (int t = 1; t <= len; t++) if (!put(bc, fs, lx, bot[idx] - t, lz, DECO[D_ROOTS])) break;
      }
      int top = tops[lx * 32 + lz];
      if (top < 0) continue;
      double r1 = hash01(x, z, 111);
      double r2 = hash01(x, z, 113);
      double r3 = hash01(x, z, 115);
      double pn = @PKG@.WgIsle.vnoise((double) x, (double) z, PATCH_S, 103);
      int hv = (int) (hash01(x, z, 107) * 1000.0);
      if (ii == 0) {
        if (r1 < 0.0016) boulder(bc, fs, lx, lz, top, tops, DECO[D_MOSSY], x, z);
        else if (pn > 0.25 && r2 < 0.16 && FLOWERS.length > 0) {
          int fi = (int) (hash01(Math.floorDiv(x, 24), Math.floorDiv(z, 24), 105) * FLOWERS.length);
          if (fi >= FLOWERS.length) fi = FLOWERS.length - 1;
          if (hash01(x, z, 106) < 0.25) fi = (fi + 3) % FLOWERS.length;
          put(bc, fs, lx, top + 1, lz, FLOWERS[fi]);
        } else if (r3 < 0.005) put(bc, fs, lx, top + 1, lz, r3 < 0.0025 ? DECO[D_RUBMOSS] : DECO[D_RUBSTONE]);
      } else if (ii == 1) {
        if (r1 < 0.0012) pillar(bc, fs, lx, top, lz, 3 + hv % 6, DECO[D_SANDRED], DECO[D_SANDCAP], DECO[D_SANDCAP]);
        else if (r2 < 0.011) put(bc, fs, lx, top + 1, lz, r2 < 0.0055 ? DECO[D_DEADBUSH] : DECO[D_DEADTWIST]);
        else if (r3 < 0.006) put(bc, fs, lx, top + 1, lz, DECO[D_RUBSAND]);
      } else if (ii == 2) {
        if (r1 < 0.0010) pillar(bc, fs, lx, top, lz, 4 + hv % 7, DECO[D_ICE], DECO[D_PERMA], DECO[D_ICE]);
        else if (r2 < 0.009) put(bc, fs, lx, top + 1, lz, DECO[D_SNOWBUSH]);
        else if (r3 < 0.005) put(bc, fs, lx, top + 1, lz, DECO[D_RUBICE]);
      } else if (ii == 3) {
        if (r1 < 0.0015) pillar(bc, fs, lx, top, lz, 3 + hv % 7, DECO[D_BASALT], 0, 0);
        else if (pn > 0.45 && r2 < 0.10) crack(bc, fs, lx, top, lz);
        else if (r2 > 0.994) put(bc, fs, lx, top + 1, lz, DECO[D_DEADTWIST]);
        else if (r3 < 0.006) put(bc, fs, lx, top + 1, lz, r3 < 0.003 ? DECO[D_RUBVOLC] : DECO[D_RUBBASALT]);
      } else {
        // Zone 5 (fix round 2: visibly its own island, not a small Zone 4): more + taller glowing spires, wide lava-crack fields, 4x the red crystals
        if (r1 < 0.0022) pillar(bc, fs, lx, top, lz, 7 + hv % 9, DECO[D_BASALT], DECO[D_GLOW], DECO[D_BASALT]);
        else if (pn > 0.25 && r2 < 0.20) crack(bc, fs, lx, top, lz);
        else if (r2 > 0.984) put(bc, fs, lx, top + 1, lz, r2 > 0.993 ? DECO[D_CRYMED] : DECO[D_CRYSMALL]);
        else if (r3 < 0.006) put(bc, fs, lx, top + 1, lz, DECO[D_RUBBASALT]);
      }
    }
  }
}""")
# ---- ZONE 4 + 5 ORES: veins in 8 x 8 x 8 cells (chance per cell, a jittered sphere), only in the host rock of the islands ORE_MASK names, at least
# ORE_COVER under its ground and over its sealed bottom shell; never a block with a state (chests, spawners)
M(zisl, r"""
public static void ores(@GC@ gc, @GBC@ bc, int bx, int bz, int[] bot, int[] tb, int[] isl) {
  for (int t = 0; t < ORE.length; t++) {
    int id = ORE[t];
    if (id <= 0) continue;
    int c0x = Math.floorDiv(bx - 4, 8);
    int c1x = Math.floorDiv(bx + 35, 8);
    int c0z = Math.floorDiv(bz - 4, 8);
    int c1z = Math.floorDiv(bz + 35, 8);
    int c0y = ORE_Y0[t] / 8;
    int c1y = ORE_Y1[t] / 8;
    for (int a = c0x; a <= c1x; a++) for (int c = c0z; c <= c1z; c++) for (int yy = c0y; yy <= c1y; yy++) {
      if (hash3(a, yy, c, 200 + t) >= ORE_P[t]) continue;
      double vx = a * 8 + 1.0 + 6.0 * hash3(a, yy, c, 210 + t);
      double vy = yy * 8 + 1.0 + 6.0 * hash3(a, yy, c, 220 + t);
      double vz = c * 8 + 1.0 + 6.0 * hash3(a, yy, c, 230 + t);
      double rr = ORE_RMIN[t] + (ORE_RMAX[t] - ORE_RMIN[t]) * hash3(a, yy, c, 240 + t);
      int xa = (int) Math.floor(vx - rr);
      int xb = (int) Math.ceil(vx + rr);
      int ya = (int) Math.floor(vy - rr);
      int yb = (int) Math.ceil(vy + rr);
      int za = (int) Math.floor(vz - rr);
      int zb = (int) Math.ceil(vz + rr);
      for (int x = xa; x <= xb; x++) for (int y = ya; y <= yb; y++) for (int z = za; z <= zb; z++) {
        int lx = x - bx;
        int lz = z - bz;
        if (lx < 0 || lx > 31 || lz < 0 || lz > 31 || y < ORE_Y0[t] || y > ORE_Y1[t] || y > 319) continue;
        int idx = (lx + 1) * 34 + (lz + 1);
        int oi = isl[idx];
        if (oi < 0 || ((ORE_MASK[t] >> oi) & 1) == 0) continue;
        if (y < bot[idx] + SHELL + 1 || y > tb[lx * 32 + lz] - ORE_COVER) continue;
        double dx = x + 0.5 - vx;
        double dy = y + 0.5 - vy;
        double dz = z + 0.5 - vz;
        if (dx * dx + dy * dy + dz * dz > rr * rr) continue;
        if (hash3(x, y, z, 250 + t) < 0.22) continue;
        if (!has(HOST, bc.getBlock(lx, y, lz))) continue;
        if (gc.getState(lx, y, lz) != null) continue;
        bc.setBlock(lx, y, lz, id, 0, 0);
        ORE_N.incrementAndGet();
      }
    }
  }
}""")
