M(zisl, r"""
public static String placeAt(@WLD@ w, double x, double y, double z) {
  @PKG@.WgZoneGen g = genOf(w);
  if (g == null) return "the zone islands generator is not running on this world";
  int seed = (int) w.getWorldConfig().getSeed();
  @PKG@.WgZoneLayout L = g.layoutReady(seed);
  if (L == null) return "the islands are still being picked from the vanilla map - try again in a few seconds";
  double[] m = new double[1];
  double px = Math.floor(x) + 0.5;
  double pz = Math.floor(z) + 0.5;
  int ii = member(L, px, pz, m);
  String s;
  if (ii >= 0) s = "on the Zone " + Z_IDS[ii] + " island (" + Z_NAMES[ii] + "), " + Math.round(m[0]) + " blocks in from its coast";
  else {
    int best = 0 - 1;
    double bd = 1.0E18;
    for (int i = 0; i < L.n; i++) {
      if (!L.found[i]) continue;
      double dx = x - L.cx[i];
      double dz = z - L.cz[i];
      double d = Math.sqrt(dx * dx + dz * dz);
      if (d < bd) { bd = d; best = i; }
    }
    s = best < 0 ? "over the void" : "over the void - the nearest island is Zone " + Z_IDS[best] + " (" + Z_NAMES[best] + "), its centre " + Math.round(bd) + " blocks away";
  }
  try {
    @ZBR@ r = g.getZoneBiomeResultAt(seed, (int) Math.floor(x), (int) Math.floor(z));
    if (r != null) s = s + "; vanilla zone " + r.getZoneResult().getZone().name() + ", biome " + r.getBiome().getName();
  } catch (Throwable t) { }
  if (ii >= 0) {
    try {
      int h = g.getHeight(seed, (int) Math.floor(x), (int) Math.floor(z));
      s = s + "; island underside here y " + bottomOf(m[0], h, px, pz) + " (vanilla ground y " + h + ")";
    } catch (Throwable t) { }
  }
  return s;
}""")
