M(z2isl, r"""
public static void mirror(@GC@ gc, @GBC@ bc, int bx, int bz, int[] bot, int[] tb, int[] isl) {
  byte[] sm = SRCMAP;
  if (sm == null || sm.length == 0) return;
  int[][] srcs = MR_SRC;
  int[][] hosts = MR_HOST;
  if (srcs.length < MR_N || hosts.length < MR_N) return;
  int act = mrActive();
  if (act == 0) return;
  boolean any = false;
  for (int c = 0; c < 1024 && !any; c++) {
    int zc = isl[(c / 32 + 1) * 34 + (c % 32) + 1];
    if (tb[c] >= 0 && zc >= 0 && ((act >> zc) & 1) != 0) any = true;
  }
  if (!any) return;
  int[] buf = new int[640];
  int nb = 0;
  for (int lx = 0; lx < 32; lx++) for (int lz = 0; lz < 32; lz++) {
    int idx = (lx + 1) * 34 + (lz + 1);
    int zi = isl[idx];
    int top = tb[lx * 32 + lz];
    if (zi < 0 || top < 0 || ((act >> zi) & 1) == 0) continue;     // not an island column / no active rule on this island
    int y0 = bot[idx] + SHELL + 1;
    if (y0 < 1) y0 = 1;
    int y1 = top - ORE_COVER;                                         // the cover band: never in the island's surface skin (critic M1)
    if (y1 > 319) y1 = 319;
    for (int y = y0; y <= y1; y++) {
      int b = bc.getBlock(lx, y, lz);
      if (b <= 0 || b >= sm.length || sm[b] == 0) continue;
      int cx = Math.floorDiv(bx + lx, 8);
      int cy = y >> 3;
      int cz = Math.floorDiv(bz + lz, 8);
      for (int r = 0; r < MR_N; r++) {
        if (MR_ISL[r] != zi || !has(srcs[r], b)) continue;
        MR_SEEN.incrementAndGet(r);
        double w0 = mw(r, 0) / 3.0;
        double w1 = mw(r, 1) / 3.0;
        double w2 = mw(r, 2) / 3.0;
        if (!(w0 > 0.0)) w0 = 0.0;
        if (!(w1 > 0.0)) w1 = 0.0;
        if (!(w2 > 0.0)) w2 = 0.0;
        double tot = w0 + w1 + w2;
        if (tot <= 0.0) continue;
        if (tot > 1.0) {
          w0 = w0 / tot;
          w1 = w1 / tot;
          w2 = w2 / tot;
        }
        for (int s = 0; s < 3; s++) {
          double u = hash3(cx, cy, cz, 300 + r * 8 + s);
          int o = 0 - 1;
          if (u < w0) o = 0;
          else if (u < w0 + w1) o = 1;
          else if (u < w0 + w1 + w2) o = 2;
          if (o < 0) continue;
          int out = o == 0 ? b : (o == 1 ? MR_O1[r] : MR_O2[r]);
          if (out <= 0) continue;
          int tx = s == 1 ? lx : 31 - lx;
          int tz = s == 0 ? lz : 31 - lz;
          int tidx = (tx + 1) * 34 + (tz + 1);
          int ttop = tb[tx * 32 + tz];
          if (isl[tidx] != zi || ttop < 0 || y > ttop - ORE_COVER || y < bot[tidx] + SHELL + 1) continue;
          if (!has(hosts[r], bc.getBlock(tx, y, tz))) continue;
          if (nb + 6 > buf.length) {
            int[] nbuf = new int[buf.length * 2];
            System.arraycopy(buf, 0, nbuf, 0, nb);
            buf = nbuf;
          }
          buf[nb] = tx;
          buf[nb + 1] = y;
          buf[nb + 2] = tz;
          buf[nb + 3] = out;
          buf[nb + 4] = r;
          buf[nb + 5] = o;
          nb += 6;
        }
      }
    }
  }
  for (int i = 0; i < nb; i += 6) {
    int tx = buf[i];
    int y = buf[i + 1];
    int tz = buf[i + 2];
    int r = buf[i + 4];
    if (!has(hosts[r], bc.getBlock(tx, y, tz))) continue;      // a copy already landed there
    if (gc.getState(tx, y, tz) != null) continue;
    bc.setBlock(tx, y, tz, buf[i + 3], 0, 0);
    MR_PUT.incrementAndGet(r * 3 + buf[i + 5]);
    ORE_N.incrementAndGet();
  }
}""")
M(z2isl, r"""
public static String mirText() {
  StringBuilder sb = new StringBuilder();
  for (int r = 0; r < MR_N; r++) {
    long seen = MR_SEEN.get(r);
    if (seen == 0L) continue;
    if (sb.length() > 0) sb.append(", ");
    sb.append(MR_NAME[r]).append(' ').append(seen).append(" -> +").append(MR_PUT.get(r * 3)).append(" / ").append(MR_PUT.get(r * 3 + 1)).append(" / ").append(MR_PUT.get(r * 3 + 2));
  }
  return sb.length() == 0 ? "none yet" : sb.toString();
}""")
