M(shome, r"""
public static int onZone1(double[] p) {
  if (p == null) return 0;
  try {
    @WLD@ w = @UNI@.get().getWorld(@PKG@.WgZones.WORLDS[@PKG@.WgZones.ZONES2]);
    if (w == null || !w.isAlive()) return 0 - 1;
    @PKG@.WgZ2Gen g = @PKG@.WgZ2Isles.genOf(w);
    if (g == null) return 0 - 1;
    @PKG@.WgZ2Layout L = g.layoutReady((int) w.getWorldConfig().getSeed());
    if (L == null) return 0 - 1;
    int ii = @PKG@.WgZ2Isles.member(L, Math.floor(p[0]) + 0.5, Math.floor(p[2]) + 0.5, new double[1]);
    if (ii < 0) return 0;
    int zz = ii < L.nMain ? ii : L.zone[ii];
    if (zz == 0) return 1;
    return 0;
  } catch (Throwable t) { return 0 - 1; }
}""")
# the trip to a landing point p of skywynn_zones2 (player's world thread): 1 = on the way; 0 - d = not possible (WgOpen.decide's code)
M(shome, r"""
public static int travel(@ST@ store, @REF@ ref, @PR@ pr, @WLD@ from, double[] p, String say) {
  if (p == null || store == null || ref == null) return 0;
  int zi = @PKG@.WgZones.ZONES2;
  String hk = pr == null || pr.getUuid() == null ? null : pr.getUuid().toString();
  int d = @PKG@.WgOpen.decide(zi, from);
  @TRF@ t = @PKG@.WgApplyLanding.transformOf(p);
  String name = @PKG@.WgZones.WORLDS[zi];
  if (d == 2) {
    if (hk != null) @PKG@.WgZoneArrive.HOPS.remove(hk);
    ((@CA@) store).addComponent(ref, @TP@.getComponentType(), @TP@.createForPlayer(from, t));
    @PKG@.WgCmds.tell(pr, say);
    SENT.incrementAndGet();
    return 1;
  }
  @CF@ f = null;
  if (d == 1) {
    @WLD@ w = @UNI@.get().getWorld(name);
    if (w == null || !w.isAlive()) return 0 - 5;
    f = @CF@.completedFuture(w);
  }
  if (d == 10) f = @PKG@.WgOpen.loadingFor(name);
  if (d == 3) f = @PKG@.WgOpen.openSaved(zi, pr);
  if (f == null) return 0 - d;
  if (hk != null) @PKG@.WgZoneArrive.HOPS.remove(hk);
  @PKG@.WgCmds.tell(pr, say);
  @INS@.teleportPlayerToLoadingInstance(ref, (@CA@) store, f, @PKG@.WgOpen.here(store, ref), t);
  SENT.incrementAndGet();
  return 1;
}""")
M(shome, r"""
public static String reason(int d) {
  String s = @PKG@.WgOpen.refusal(d, @PKG@.WgZones.ZONES2);
  if (s != null) return s.startsWith("-") ? s.substring(1) : s;
  if (d == 4) return "the zone islands world was never made here - /zone 1 makes it";
  if (d == 0) return "nothing to send";
  return "the zone islands world is not reachable (code " + d + ")";
}""")
# the server spawn: true = the player is on the way to the Zone 1 landing; false = the caller keeps the vanilla behaviour (one WARN per
