M(shome, r"""
public static boolean send(@ST@ store, @REF@ ref, @PR@ pr, @WLD@ from, String what) {
  if (!@PKG@.WgCfg.SPAWN_ON) return false;
  double[] p = @PKG@.WgCfg.parseSpawn(@PKG@.WgCfg.ZSPAWN);
  if (p == null) {
    if (@PKG@.WgLog.once("spawn:none")) @PKG@.WgLog.warn("Zone 1 = server spawn is ON but no Zone 1 landing is set yet - " + what + " keeps the vanilla spawn until an admin stands on the Zone 1 island and uses /zone setlanding (or types it in Server Setup > World Gen > Zone 1 landing)");
    return false;
  }
  if (!@PKG@.WgCfg.ON || !@PKG@.WgCfg.NEW06) {
    if (@PKG@.WgLog.once("spawn:off")) @PKG@.WgLog.warn("Zone 1 = server spawn is ON but the zone islands world is switched off (Server Setup > World Gen) - " + what + " keeps the vanilla spawn");
    return false;
  }
  int r = 0;
  String why = null;
  int z = onZone1(p);
  if (z == 0) { r = 0 - 100; why = "the landing " + @PKG@.WgCfg.ZSPAWN + " is not on the Zone 1 island - set it again with /zone setlanding on Zone 1"; }
  else if (z < 0) { r = 0 - 101; why = "the zone islands world is not loaded or its islands are not picked yet, so the landing cannot be checked"; }
  else {
    try { r = travel(store, ref, pr, from, p, "=[Zone] To Zone 1 - the server spawn..."); }
    catch (Throwable t) { r = 0 - 99; why = String.valueOf(t); }
  }
  if (r == 1) return true;
  if (why == null) why = reason(0 - r);
  if (@PKG@.WgLog.once("spawn:no" + r)) @PKG@.WgLog.warn("could not send " + (pr == null ? "a player" : pr.getUsername()) + " to the Zone 1 landing for " + what + " (" + why + ") - the vanilla spawn instead");
  return false;
}""")
